CREATE TABLE "public"."notification_escalation_rules" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."notification_escalation_rules_id_seq" START WITH 1 INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 CACHE 1 NO CYCLE) NOT NULL,
  "rule_key" text NOT NULL,
  "rule_name" text NOT NULL,
  "category" text NOT NULL,
  "event_type" text,
  "source_priority" text DEFAULT 'High'::text NOT NULL,
  "first_repeat_after_minutes" integer,
  "escalation_after_minutes" integer NOT NULL,
  "repeat_every_minutes" integer,
  "maximum_repeat_count" integer,
  "escalation_target_role" text,
  "escalation_target_user_id" uuid,
  "project_scope_required" boolean DEFAULT false NOT NULL,
  "is_enabled" boolean DEFAULT true NOT NULL,
  "created_by_user_id" uuid,
  "updated_by_user_id" uuid,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL
) USING "heap";
ALTER TABLE "public"."notification_escalation_rules" OWNER TO "postgres";
COMMENT ON TABLE "public"."notification_escalation_rules" IS 'Explicit and auditable overdue-notification escalation configuration.';
COMMENT ON COLUMN "public"."notification_escalation_rules"."rule_key" IS 'Stable unique identifier for an escalation policy.';
COMMENT ON COLUMN "public"."notification_escalation_rules"."first_repeat_after_minutes" IS 'Delay before repeating the unresolved notification to the original recipient.';
COMMENT ON COLUMN "public"."notification_escalation_rules"."escalation_after_minutes" IS 'Delay before creating a separate notification for an authorized escalation recipient.';
COMMENT ON COLUMN "public"."notification_escalation_rules"."repeat_every_minutes" IS 'Optional controlled recurrence interval after the first repeat or escalation.';
COMMENT ON COLUMN "public"."notification_escalation_rules"."maximum_repeat_count" IS 'Optional maximum number of controlled repeat notifications.';
COMMENT ON COLUMN "public"."notification_escalation_rules"."project_scope_required" IS 'Requires the escalation recipient project scope to match the notification project context.';
